const formatBytes=value=>{const n=Number(value||0);if(n<1024)return money(n)+' بایت';if(n<1024**2)return (n/1024).toFixed(1)+' کیلوبایت';if(n<1024**3)return (n/1024**2).toFixed(2)+' مگابایت';return (n/1024**3).toFixed(2)+' گیگابایت';};
