 useEffect(()=>{let active=true;(async()=>{if(!session){setAdminOk(false);setCheckingAdmin(false);return;}setCheckingAdmin(true);try{const [profileResult,adminResult]=await Promise.all([supabase.from('profiles').select('role').eq('id',session.user.id).maybeSingle(),supabase.from('store_admins').select('user_id').eq('user_id',session.user.id).maybeSingle()]);if(active)setAdminOk(!profileResult.error&&!adminResult.error&&profileResult.data?.role==='admin'&&!!adminResult.data);}catch{if(active)setAdminOk(false);}finally{if(active)setCheckingAdmin(false);}})();return()=>{active=false;};},[session]);
 async function refreshStorageUsage(){if(!supabase)return;setStorageUsage(v=>({...v,loading:true,error:''}));try{const queue=[''];let bytes=0,count=0;while(queue.length){const folder=queue.shift();let offset=0;while(true){const {data,error}=await supabase.storage.from('product-images').list(folder,{limit:1000,offset,sortBy:{column:'name',order:'asc'}});if(error)throw error;const rows=data||[];for(const item of rows){if(!item.id&&!item.metadata){queue.push(folder?folder+'/'+item.name:item.name);}else{bytes+=Number(item.metadata?.size||0);count++;}}if(rows.length<1000)break;offset+=1000;}}setStorageUsage({bytes,count,loading:false,error:''});}catch(error){setStorageUsage(v=>({...v,loading:false,error:'خواندن فضای ذخیره‌سازی ممکن نشد؛ دسترسی فهرست فایل‌ها یا اتصال را بررسی کنید.'}));}}
